use vstd::prelude::*;
use vstd::vec::Vec;

/**
 Verus‐specification for numpy_append:
  - Ensures that the returned Vec has length equal to the sum of the
    two input Vecs' lengths.
  - Ensures that its contents are exactly the concatenation of the
    two input Vecs.
*/
#[requires(true)]
#[ensures(result.len() == arr.len() + values.len())]
#[ensures(result.to_seq() == arr.to_seq().concat(values.to_seq()))]
fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Move `arr` into `result`
    let mut result = arr;
    // Reserve enough space so that extend does not reallocate
    result.reserve(values.len());
    // After reserve, verify that the length and contents are unchanged
    assert(result.len() == arr.len());
    assert(result.to_seq() == arr.to_seq());

    // Perform the extend (this has its own Verus spec in vstd)
    result.extend(values);

    // After extend, verify the post‐conditions hold locally
    assert(result.len() == arr.len() + values.len());
    assert(result.to_seq() == arr.to_seq().concat(values.to_seq()));

    result
}

